package behavioral.iterator.sample;

public interface IIterator<T> {
    boolean hasNext();
    T next();
}

package behavioral.iterator.sample;

public class Main {

    public static void main(String[] args) {
        String[] songs = {
            "Song A",
            "Song B",
            "Song C"
        };
        Playlist playlist = new Playlist(songs);
        IIterator<String> iterator = playlist.createIterator();
        while (iterator.hasNext()) {
            String song = iterator.next();
            System.out.println(song);
        }
    }
}

package behavioral.iterator.sample;

public class Playlist {
    private final String[] songs;

    public Playlist(String[] songs) {
        this.songs = songs;
    }

    public IIterator<String> createIterator() {
        return new PlaylistIterator(songs);
    }
}

package behavioral.iterator.sample;

public class PlaylistIterator implements IIterator<String> {
    private final String[] songs;
    private int index = 0;

    public PlaylistIterator(String[] songs) {
        this.songs = songs;
    }

    @Override
    public boolean hasNext() {
        return index < songs.length;
    }

    @Override
    public String next() {
        String currentSong = songs[index];
        index++;
        return currentSong;
    }
}

